cypress_script:
describe('Horizontal Slider Control', () => {
  it('should adjust the slider and display the correct value', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('input[type="range"]').invoke('val', 50).trigger('change');
    cy.get('#range').should('have.text', '50');
  });
  it('should not change the value when the slider is not adjusted', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('#range').should('have.text', '0');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Horizontal Slider Control', () => {
  test('should adjust the slider and display the correct value', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    const slider = await page.locator('input[type="range"]');
    await slider.fill('50');
    await slider.dispatchEvent('change');
    const rangeValue = await page.locator('#range');
    await expect(rangeValue).toHaveText('50');
  });
  test('should not change the value when the slider is not adjusted', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    const rangeValue = await page.locator('#range');
    await expect(rangeValue).toHaveText('0');
  });
});
